INSERT INTO "materials" ("id", "name_zh", "name_en", "type", "rarity", "description_zh", "source", "usage", "image", "sort_order") VALUES
  (201, '原石', 'Primogem', 'valuable', 5, '超出世界的原初晶石。黑暗的宇宙中，由无主的梦想与希望凝结而成的辉光。', NULL, NULL, 'UI_ItemIcon_201.webp', 0),
  (202, '摩拉', 'Mora', 'valuable', 3, '通行大陆的钱。世界通用的共同语言，谁人都能理解的贵金属。', NULL, NULL, 'UI_ItemIcon_202.webp', 0),
  (203, '创世结晶', 'Genesis Crystal', 'valuable', 5, '开辟宇宙的能量结晶。虚无的真空中，由足以点亮新星的潜力和希望结晶而成。', NULL, NULL, 'UI_ItemIcon_203.webp', 0),
  (221, '无主的星辉', 'Masterless Starglitter', 'valuable', 5, '可以在商城兑换珍稀资源的货币。
过剩的命运星之光辉。或许可以点亮宇宙其他角落。', NULL, NULL, 'UI_ItemIcon_221.webp', 0),
  (222, '无主的星尘', 'Masterless Stardust', 'valuable', 4, '可以在商城兑换珍稀资源的货币。
过剩的命运星之晶尘。累积起来，或许可以创造新的命运。', NULL, NULL, 'UI_ItemIcon_222.webp', 0),
  (223, '纠缠之缘', 'Intertwined Fate', 'valuable', 5, '连结梦想的命运之种。
缘石辉光能让本无交集的命运交错，让彼此的梦想相连，正如这种光辉将群星连成心之所向的图形。', NULL, NULL, 'UI_ItemIcon_223.webp', 0),
  (224, '相遇之缘', 'Acquaint Fate', 'valuable', 5, '点亮星空的希望之种。
无论相隔多远，命定相遇的人都会受缘石辉光的指引，在星空下相会。', NULL, NULL, 'UI_ItemIcon_224.webp', 0),
  (100021, '钩钩果', 'Wolfhook', 'local_specialty', 1, '带着勾刺的莓果，会挂在狼的毛皮上来迁徙。看见它时，仿佛能听见狼的凄嚎在林间回荡…', '推荐：奔狼领采集', NULL, 'UI_ItemIcon_100021.png', 0),
  (100022, '落落莓', 'Valberry', 'local_specialty', 1, '饱满透亮的莓果，在口中绽放出清甜的花香。在过去，守望风暴的人仅有的慰藉便是落落莓的甜蜜与对城市安宁的希望。', '推荐：望风山地采集；尘歌壶种植', NULL, 'UI_ItemIcon_100022.png', 0),
  (100023, '塞西莉亚花', 'Cecilia', 'local_specialty', 1, '名字与外形同等美丽的花朵，只生长在清冷而风急的高处，如同浪子一样真心难以触碰。', '推荐：摘星崖采集；尘歌壶种植', NULL, 'UI_ItemIcon_100023.png', 0),
  (100024, '风车菊', 'Windwheel Aster', 'local_specialty', 1, '喜好风的植物。对于崇信风、本身也如风一般爽朗自在的蒙德人而言，风车菊便是「看得见的风」。', '风起地七天神像附近采集；推荐：风龙废墟采集；尘歌壶种植', NULL, 'UI_ItemIcon_100024.png', 0),
  (100025, '慕风蘑菇', 'Philanemo Mushroom', 'local_specialty', 1, '沐浴着和煦的风而生长的菌类，与风一样生生不息，滋养生命。', '房檐下采集', NULL, 'UI_ItemIcon_100025.png', 0),
  (100027, '绝云椒椒', 'Jueyun Chili', 'local_specialty', 1, '璃月地方特产的辛辣植物。只要闻到它的味道，身体就会变得炽热，渴求水分。', '推荐：轻策庄采集；尘歌壶种植', NULL, 'UI_ItemIcon_100027.png', 0),
  (100028, '夜泊石', 'Noctilucous Jade', 'local_specialty', 1, '稀有的特质矿石，在静谧的暗夜里会幽幽地发光。据称是天地间奔流的元素在异变中凝聚成的珍奇宝石。', '璃月山洞内采集；推荐：明蕴镇采集', NULL, 'UI_ItemIcon_100028.png', 0),
  (100029, '霓裳花', 'Silk Flower', 'local_specialty', 1, '在璃月如霓云般盛放的妖红之花，能制成如水般顺滑的织物。', '璃月港玉京台附近采集；望舒客栈附近采集；尘歌壶种植', NULL, 'UI_ItemIcon_100029.png', 0),
  (100030, '琉璃百合', 'Glaze Lily', 'local_specialty', 1, '极为古老的花卉。据说曾经遍布璃月大地，能将大地的记忆积攒成花期时的芬芳。', '推荐：璃月港玉京台采集；推荐：轻策庄采集；尘歌壶种植', NULL, 'UI_ItemIcon_100030.png', 0),
  (100031, '清心', 'Qingxin', 'local_specialty', 1, '只生长在孤高石峰的通透白花。不愿接受平原的温暖与湿润，宁可在清冷的尖峰眺望远方。', '推荐：绝云间采集；推荐：孤云阁采集；尘歌壶种植', NULL, 'UI_ItemIcon_100031.png', 0),
  (100033, '星螺', 'Starconch', 'local_specialty', 1, '随着海潮来到沙滩上的螺。将耳朵凑近空壳，能听见海充满思念的呼唤。', '璃月海滩采集', NULL, 'UI_ItemIcon_100033.png', 0),
  (100034, '琉璃袋', 'Violetgrass', 'local_specialty', 1, '拥有旺盛生命力的小花，传说朝下盛开的花姿是为了守住它的香气。', '璃月山壁采集；尘歌壶种植', NULL, 'UI_ItemIcon_100034.png', 0),
  (100055, '小灯草', 'Small Lamp Grass', 'local_specialty', 1, '在夜间会隐隐散发辉光的野花。与其他食材一同烹饪能提升鲜味。', '推荐：奔狼领采集；推荐：低语森林采集；尘歌壶种植', NULL, 'UI_ItemIcon_100055.png', 0),
  (100056, '嘟嘟莲', 'Calla Lily', 'local_specialty', 1, '生长在水边的花。花瓣经过烹制口感爽脆，清甜微苦。', '湖泊水边采集；推荐：清泉镇采集；尘歌壶种植', NULL, 'UI_ItemIcon_100056.png', 0),
  (100057, '蒲公英籽', 'Dandelion Seed', 'local_specialty', 1, '随风而行的细小种子。即使拔去了旅行的羽絮，其中也寄宿着远方的希望吧。', '推荐：蒙德城门采集', NULL, 'UI_ItemIcon_100057.png', 0),
  (100058, '石珀', 'Cor Lapis', 'local_specialty', 1, '极纯的岩元素凝成的珍稀晶石，常与其他矿物伴生。也被称为「岩之心」。', '璃月山壁下采集；推荐：琥牢山采集', NULL, 'UI_ItemIcon_100058.png', 0),
  (101201, '鬼兜虫', 'Onikabuto', 'local_specialty', 1, '栖息在雷元素富集区域的奇异甲虫。与甲壳上宛如怒目而视的恶鬼之相相反，鬼兜虫其实非常温顺迟钝。', '推荐：鸣神岛采集；推荐：踏鞴砂采集', NULL, 'UI_ItemIcon_101201.png', 0),
  (101202, '绯樱绣球', 'Sakura Bloom', 'local_specialty', 1, '从鸣神大社的神樱上飘落的花瓣，怀着稻妻大地的眷顾。', '推荐：鸣神岛采集', NULL, 'UI_ItemIcon_101202.png', 0),
  (101203, '晶化骨髓', 'Crystal Marrow', 'local_specialty', 1, '蕴含着「祟神」力量的晶体。冶炼时加入这种物质的话，能极大地提高钢铁制品的强度与韧性。', '推荐：八酝岛采集', NULL, 'UI_ItemIcon_101203.png', 0),
  (101204, '血斛', 'Dendrobium', 'local_specialty', 1, '在诗文中也被称为「赤蕊」的鲜艳植物，一度在稻妻列岛绝迹，如今在战场上再度重现。传说在血腥的战场上，它们开得格外妖艳。', '推荐：名椎滩采集', NULL, 'UI_ItemIcon_101204.png', 0),
  (101205, '鸣草', 'Naku Weed', 'local_specialty', 1, '即使在无风的日子里，亦会随雷鸣之声隐隐振动的植物。看起来像是花瓣的结构其实是叶片的延伸，保护着脆弱的花朵。', '推荐：踏鞴砂采集；尘歌壶种植', NULL, 'UI_ItemIcon_101205.png', 0),
  (101206, '海灵芝', 'Sea Ganoderma', 'local_specialty', 1, '在某些特殊的海域中、岛屿上才会生长的特殊物种。虽然外形看起来像菌类，但其实是由软体生物分泌增生而成的。', '稻妻海域采集；尘歌壶种植', NULL, 'UI_ItemIcon_101206.png', 0),
  (101207, '珊瑚真珠', 'Sango Pearl', 'local_specialty', 1, '与海祇的珊瑚相伴而生的宝珠，散发着月光般的丝丝凉意。', '推荐：海祇岛采集', NULL, 'UI_ItemIcon_101207.png', 0),
  (101208, '天云草实', 'Amakumo Fruit', 'local_specialty', 1, '生长在清籁岛的天云草结成的果实，贴在耳畔能听见微弱的电流声。', '推荐：清籁岛采集', NULL, 'UI_ItemIcon_101208.png', 0),
  (101209, '幽灯蕈', 'Fluorescent Fungus', 'local_specialty', 1, '如同夜灯般微微发光的蘑菇，其中蕴含着不可思议的力量。', '推荐：鹤观采集', NULL, 'UI_ItemIcon_101209.png', 0),
  (101213, '树王圣体菇', 'Rukkhashava Mushrooms', 'local_specialty', 1, '如云海般层层叠叠生长的菌类，大多寄生于雨林深处的乔木之上。', '推荐：善见地采集；推荐：护世森采集', NULL, 'UI_ItemIcon_101213.png', 0),
  (101214, '帕蒂沙兰', 'Padisarah', 'local_specialty', 1, '圣洁而高贵的花卉，对生长环境的要求十分苛刻。花蕊经过加工后可以制成珍贵的香料。', '须弥城附近采集', NULL, 'UI_ItemIcon_101214.png', 0),
  (101215, '月莲', 'Nilotpala Lotus', 'local_specialty', 1, '生长于林中湿地，散发着同月亮一般皎洁光芒的花卉。只有在夜晚才会绽放。', '须弥水域采集', NULL, 'UI_ItemIcon_101215.png', 0),
  (101217, '劫波莲', 'Kalpalata Lotus', 'local_specialty', 1, '生长在山崖峭壁之上的攀援植物开出的花朵。被称为莲只是因为外形相似，本身和莲花并没有什么关系。', '须弥山崖采集', NULL, 'UI_ItemIcon_101217.png', 0),
  (101220, '赤念果', 'Henna Berry', 'local_specialty', 1, '在恶劣的沙漠环境中也能存活的植物所结的果子，赤红的果实在黄沙映衬下显得格外动人。', '须弥沙漠采集', NULL, 'UI_ItemIcon_101220.png', 0),
  (101222, '沙脂蛹', 'Sand Grease Pupa', 'local_specialty', 1, '在沙漠深处流沙鳗鳗的繁殖地才能找到的枯壳。其坚硬的表壳是为了保护流沙鳗鳗的幼体，直到它们得以适应炎热干燥的沙漠环境而存在的。', '须弥沙漠采集；推荐：沙虫隧道采集', NULL, 'UI_ItemIcon_101222.png', 0),
  (101223, '悼灵花', 'Mourning Flower', 'local_specialty', 1, '绽放在古老战场上的鲜红之花，即便在荒漠中也能顽强生长。低垂的花朵似乎是在哀悼曾在此牺牲的英灵。', '须弥沙漠采集；推荐：锋刃林泽采集', NULL, 'UI_ItemIcon_101223.png', 0),
  (101224, '万相石', 'Trishiraite', 'local_specialty', 1, '分布在荒原群山的深处，散发着异彩的特殊辉石，似乎是由混化的元素能量凝结而成的。', '须弥沙漠采集；推荐：铁穆山采集', NULL, 'UI_ItemIcon_101224.png', 0),
  (101225, '圣金虫', 'Scarab', 'local_specialty', 1, '栖息在浩瀚沙海之中的顽强甲虫。甲壳上的金色纹路似乎暗示着它们与遍布沙漠的古老遗迹间存在某种渊源。', '须弥沙漠遗迹采集', NULL, 'UI_ItemIcon_101225.png', 0),
  (101232, '苍晶螺', 'Beryl Conch', 'local_specialty', 1, '散发着幽光的贝状结构。似乎是纯净的元素能量凝结而成的产物，而非某种生物的甲壳。', '推荐：塞洛海原采集', NULL, 'UI_ItemIcon_101232.png', 0),
  (101233, '海露花', 'Romaritime Flower', 'local_specialty', 1, '幽淡而高贵的蓝色花卉。柔软的花蕊具备良好的吸水性和弹性，是诸多日用品的原材料。', '推荐：塞洛海原采集', NULL, 'UI_ItemIcon_101233.png', 0),
  (101235, '柔灯铃', 'Lumidouce Bell', 'local_specialty', 1, '静雅而清美的紫色花卉。其香清淡悠长、细腻柔和，因此常被用来制作名贵的香水。', '枫丹廷北部采集；尘歌壶种植', NULL, 'UI_ItemIcon_101235.png', 0),
  (101236, '虹彩蔷薇', 'Rainbow Rose', 'local_specialty', 1, '纤婉而柔洁的粉色花卉。虽然被称作蔷薇，但本质上更接近百合。', '推荐：苍晶区采集；尘歌壶种植', NULL, 'UI_ItemIcon_101236.png', 0),
  (101237, '幽光星星', 'Lumitoile', 'local_specialty', 1, '在水中会发出柔浅微光的软体动物。大多攀附在水边或水下的人造建筑表面。', '推荐：黎翡区采集', NULL, 'UI_ItemIcon_101237.png', 0),
  (101238, '湖光铃兰', 'Lakelight Lily', 'local_specialty', 1, '明澈而澄净的苍色花卉。生于水脉汇聚之处，其香清冷淡雅，辛凉柔婉。', '推荐：伊黎耶林区采集', NULL, 'UI_ItemIcon_101238.png', 0),
  (101239, '子探测单元', 'Subdetection Unit', 'local_specialty', 1, '枫丹科学院利用新型奇械构件生产的微型探测单元，原本用以监测各类环境数据。', '推荐：枫丹动能工程科学研究院区采集', NULL, 'UI_ItemIcon_101239.png', 0),
  (101240, '初露之源', 'Spring of the First Dewdrop', 'local_specialty', 1, '悬浮于莫尔泰区水体深处的清澈露滴，与常见的纯水造物不同，似乎凝聚着更为原始而纯粹的元素能量。', '推荐：莫尔泰区水下采集', NULL, 'UI_ItemIcon_101240.png', 0),
  (101241, '清水玉', 'Clearwater Jade', 'local_specialty', 1, '出产于沉玉谷的玉石。触感凉如清水，因此而得名。', '野外采集；推荐：沉玉谷·南陵采集', NULL, 'UI_ItemIcon_101241.png', 0),
  (101247, '浪沫羽鳃', 'Sprayfeather Gill', 'local_specialty', 1, '生长在海边如羽状的特殊物种，看似是水草般的植物，实际上是形态特殊的水栖软体珊瑚。', '推荐：涌流地采集；推荐：「流泉之众」周边采集；尘歌壶种植', NULL, 'UI_ItemIcon_101247.png', 0),
  (101248, '灼灼彩菊', 'Brilliant Chrysanthemum', 'local_specialty', 1, '形如飘然羽翼的花，花瓣的姿态在风中无比悠然。', '推荐：柴薪之丘采集；推荐：圣火竞技场周边采集；尘歌壶种植', NULL, 'UI_ItemIcon_101248.png', 0),
  (101249, '青蜜莓', 'Quenepa Berry', 'local_specialty', 1, '青蓝色的，汁液丰富的莓果。其果树大片生长在「悬木人」部族附近，是形态与火榴果相近的植物。', '推荐：踞石山采集；推荐：「悬木人」下方采集；尘歌壶种植', NULL, 'UI_ItemIcon_101249.png', 0),
  (101250, '肉龙掌', 'Saurian Claw Succulent', 'local_specialty', 1, '形如巨大动物爪掌的多肉植物。', '推荐：硫晶支脉采集；尘歌壶种植', NULL, 'UI_ItemIcon_101250.png', 0),
  (101252, '微光角菌', 'Glowing Hornshroom', 'local_specialty', 1, '在黑暗中微微发出光芒的菌类，因为形似暝视龙的角冠而被称为角菌。', '推荐：镜璧山采集；推荐：「烟谜主」周边采集；尘歌壶种植', NULL, 'UI_ItemIcon_101252.png', 0),
  (101253, '枯叶紫英', 'Withering Purpurbloom', 'local_specialty', 1, '叶片与花瓣呈现枯焦之态的花朵，常常能在流灰弥漫之处看到它。', '推荐：奥奇卡纳塔采集', NULL, 'UI_ItemIcon_101253.png', 0),
  (101254, '云岩裂叶', 'Skysplit Gembloom', 'local_specialty', 1, '花叶的外侧犹如石质的奇特植物，在绽放后，会露出晶石一般的芯。', '推荐：安饶之野采集；尘歌壶种植', NULL, 'UI_ItemIcon_101254.png', 0),
  (101255, '琉鳞石', 'Dracolite', 'local_specialty', 1, '沉积在富含燃素的区域，逐渐形成的红色鳞状晶石，蕴含极高的热量。', '推荐：安饶之野采集', NULL, 'UI_ItemIcon_101255.png', 0),
  (101257, '便携轴承', 'Portable Bearing', 'local_specialty', 1, '愚人众进驻挪德卡莱后大量制造的便携轴承单元。损耗过度的单元也会像失去用途的单位一样被抛弃。
其中偶尔还会残存一些微弱的月矩力。由于难以仿造，有时也会被那夏镇的商人当作等价交换的凭物。
也正是因为如此，据说曾经有人试图伪造过这些单元。最终似乎是因为伪造的成本高于它们作为一般等价物的价格而破产了。', '蓝珀湖附近采集；推荐：叮铃哐啷蛋卷工坊采集', NULL, 'UI_ItemIcon_101257.png', 0),
  (101261, '霜盏花', 'Frostlamp Flower', 'local_specialty', 1, '形如烛盏的花卉，多生长在水边，香气寒冽素净，有安神的功效。
花蕊与花茎彼此相异的色彩被认为是两种不同的月矩力的象征，然而霜盏花却是极为罕有的、不会受到月矩力任何影响的植物，因此有时也会被霜月之子的追随者们视为无信者与叛离者的象征。
据说五百年前的漆黑灾厄结束时，这种造型奇异的花朵才出现在大地上，但这种说法从未得到过严谨的考证。', '推荐：终夜长茔采集；推荐：霜月之坊附近采集；尘歌壶种植', NULL, 'UI_ItemIcon_101261.png', 0),
  (101263, '月落银', 'Moonfall Silver', 'local_specialty', 1, '如月光一般明净无瑕的银白晶体，具有几乎完美的元素亲和力。
在霜月之子的传承中，这种晶石于五百年前伴随月之少女一同诞生，被彼时的咏月使认为是从月上落下的馈赠，因此得名「月落银」。然而在至冬的编年者们记述的、更为古老的文献中，黄金国的遗胤自数千年前便在使用霜月纺就的秘银。两者之间的关联早已无从考证，唯一能确定的只有这种晶石如今依然被挪德卡莱的工匠们视为绝佳的元素力导体。', '希汐岛采集', NULL, 'UI_ItemIcon_101263.png', 0),
  (101268, '冬凌草', 'Winter Icelea', 'local_specialty', 1, '生命力极其顽强的花草，即便历经风吹霜打，依旧在苦寒的冬日里迎风摇曳。', '厄布拉神柱采集；推荐：安瓦蒂尼尔湖附近采集；尘歌壶种植', NULL, 'UI_ItemIcon_101266.png', 0),
  (101269, '松珀香', 'Pine Amber', 'local_specialty', 1, '古时覆盖挪德卡莱的参天巨木，流淌下的树脂凝结而成的宝石，散发着璀璨的色彩。', '噩影泽地采集；推荐：西风戍垒附近采集；尘歌壶种植', NULL, 'UI_ItemIcon_101269.png', 0),
  (101272, '空羽蛾', 'Etherwing Moth', 'local_specialty', 1, '闪耀着神圣金色光辉的奇异生命，如飞蛾般游曳在同样奇异的隙间。', '推荐：风息山、空之神殿采集；推荐：风车镇、柱殿中央区采集', NULL, 'UI_ItemIcon_101272.webp', 0),
  (101275, '霜仙花', 'Frostfairy Flower', 'local_specialty', 1, '不管风雪多么严苛亦会绽放的圣洁花朵，总是散发着微弱的令人向往的光芒。', '推荐：至冬采集', NULL, 'UI_ItemIcon_101275.webp', 0),
  (101276, '植绒草', 'Flockingweed', 'local_specialty', 1, '一度被怀疑是植物与动物结合后的奇妙植株，但后来被证明只不过是单纯长着类似动物绒毛的植物罢了。', '推荐：至冬采集', NULL, 'UI_ItemIcon_101276.png', 0),
  (104001, '流浪者的经验', 'Wanderer''s Advice', 'common', 2, '角色经验素材，含有1000点经验值。
如果不在大陆七国生活，这些经验还是很必要的。', NULL, NULL, 'UI_ItemIcon_104001.webp', 0),
  (104002, '冒险家的经验', 'Adventurer''s Experience', 'common', 3, '角色经验素材，含有5000点经验值。
如果踏上了前人未至的秘境，这些经验还是很重要的。', NULL, NULL, 'UI_ItemIcon_104002.webp', 0),
  (104003, '大英雄的经验', 'Hero''s Wit', 'common', 4, '角色经验素材，含有20000点经验值。
如果向往着天空岛而在大陆开始巡礼，这些经验可称得上弥足珍贵。', NULL, NULL, 'UI_ItemIcon_104003.webp', 0),
  (104101, '璀璨原钻碎屑', 'Brilliant Diamond Sliver', 'character_ascension', 2, '角色突破素材。
