INSERT INTO "character_constellations" ("id", "character_id", "level", "name_zh", "description_zh", "icon", "element_id") VALUES
  (2, 10000007, 1, '1.回转的怒风', '[color=#eab308]风涡剑[/color]可将周围5米内的敌人与物体缓慢牵引到角色面前。', 'UI_Talent_S_PlayerWind_01.webp', 3),
  (3, 10000089, 1, '1. 「爱是难驯鸟，哀乞亦无用。」', '施放[color=#FFD780]万众狂欢[/color]时，芙宁娜获得150点「气氛值」。
此外，芙宁娜持有「气氛值」的上限提升100点。', 'UI_Talent_S_Furina_01.webp', NULL),
  (4, 10000089, 2, '2. 「女人皆善变，仿若水中萍。」', '[color=#FFD780]万众狂欢[/color]持续期间，芙宁娜通过队伍中附近角色的当前生命值提升或降低的方式获得的「气氛值」提升250%。基于「气氛值」超过上限的部分，每1点「气氛值」都将使芙宁娜的生命值上限提升0.35%。至多通过这种方式使芙宁娜的生命值上限提升140%。', 'UI_Talent_S_Furina_04.webp', NULL),
