-- character_related_effects
-- ----------------------------------------------------------------------------
INSERT INTO "character_related_effects" ("id", "character_id", "name", "content", "sort_order") VALUES
  (1, 10000150, '[color=#FFD780][b]独舞倒影[/b][/color]', '[color=#e2e8f0]与奥黛塔一同起舞的心象倒影，可以通过施放元素战技或元素爆发召唤至场上。
会交替呈现[color=#ffd780][b]拂羽[/b][/color]与[color=#ffd780][b]旋翼[/b][/color]两种舞步，以优雅轻盈的舞姿间歇性攻击附近的敌人，造成[color=#99ffff][b]冰元素范围伤害[/b][/color]。
同时至多存在一个奥黛塔自己创造的[color=#ffd780][b]独舞倒影[/b][/color]。

此外，附近存在奥黛塔自己召唤的[color=#ffd780][b]独舞倒影[/b][/color]时，奥黛塔的元素战技[color=#ffd780][b]柔板·幻灵夜舞[/b][/color]将会被替换为特殊的元素战技[color=#ffd780][b]柔板·破晓终奏[/b][/color]。[/color]', 1),
  (2, 10000150, '[color=#FFD780][b]柔板·破晓终奏[/b][/color]', '[color=#e2e8f0]奥黛塔的特殊元素战技，对附近的敌人持续造成[/color][color=#99ffff][b]冰元素范围伤害[/b][/color][color=#e2e8f0]，并在共舞结束时，造成一次视为星超导反应伤害的[/color][color=#99ffff][b]冰元素范围伤害[/b][/color][color=#e2e8f0]。共舞时，奥黛塔可以控制舞步的方向。[/color]
[color=#ffd780][b]辉映·星烁[/b][/color][color=#e2e8f0]：共舞结束时，改为造成一次视为对应星反应伤害的[/color][color=#99ffff][b]冰元素范围伤害[/b][/color][color=#e2e8f0]。[/color]

[color=#e2e8f0]此外，施放特殊元素战技[/color][color=#ffd780][b]柔板·破晓终奏[/b][/color][color=#e2e8f0]后，在[/color][color=#ffd780][b]独舞倒影[/b][/color][color=#e2e8f0]剩余持续时间内，若奥黛塔处于[/color][color=#ffd780][b]辉映·星烁[/b][/color][color=#e2e8f0]状态，则[/color][color=#ffd780][b]独舞倒影[/b][/color][color=#e2e8f0]的两种舞步还会额外造成视为对应星反应伤害的[/color][color=#99ffff][b]冰元素范围伤害[/b][/color][color=#e2e8f0]。[/color]', 2),
  (3, 10000150, '[color=#FFD780][b]华彩[/b][/color]', '[color=#e2e8f0]解锁固有天赋「获选者的春祭」后，奥黛塔召唤[/color][color=#ffd780][b]独舞倒影[/b][/color][color=#e2e8f0]时将会获得的特殊效果。[/color]
[color=#e2e8f0]每层[/color][color=#ffd780][b]华彩[/b][/color][color=#e2e8f0]都会使角色造成的星烁反应伤害提升15%，持续至[/color][color=#ffd780][b]独舞倒影[/b][/color][color=#e2e8f0]退场或重新召唤[/color][color=#ffd780][b]独舞倒影[/b][/color][color=#e2e8f0]。[/color]
[color=#e2e8f0]当奥黛塔处于队伍后台时，奥黛塔每秒会清除1层[/color][color=#ffd780][b]华彩[/b][/color][color=#e2e8f0]，并使队伍中附近的其他角色获得对应层数的[/color][color=#ffd780][b]华彩[/b][/color][color=#e2e8f0]。[/color]', 3),
  (4, 10000150, '[color=#FFD780][b]擢升[/b][/color]', '特殊的伤害提升效果，与其他的伤害提升效果分别独立计算。', 4),
  (5, 10000148, '[color=#FFD780][b]弋猎印记[/b][/color]', '[color=#e2e8f0]阿罗夏向敌人施加的特殊效果。[/color]
[color=#e2e8f0]对已经处于[/color][color=#ffd780][b]弋猎印记[/b][/color][color=#e2e8f0]影响下的敌人再次施加该效果时，将会改为激活[/color][color=#ffd780][b]弋猎印记[/b][/color][color=#e2e8f0]：移除该印记，并使队伍中附近的所有角色获得[/color][color=#ffd780][b]猎者之准[/b][/color][color=#e2e8f0]效果，使其攻击力提升，持续15秒。[/color]', 1),
  (6, 10000148, '[color=#FFD780][b]图加林[/b][/color]', '[color=#e2e8f0]深受阿罗夏信赖的猎犬伙伴，可以通过施放元素爆发[/color][color=#ffd780][b]守猎进踞[/b][/color][color=#e2e8f0]召唤至场上。[/color]
[color=#e2e8f0]若周围存在敌人，每隔2秒，图加林将快速移动至一名敌人附近，对其进行撕咬攻击，造成[/color][color=#ffd780][b]雷元素伤害[/b][/color][color=#e2e8f0]。若命中的敌人处于[/color][color=#ffd780][b]弋猎印记[/b][/color][color=#e2e8f0]效果影响下，还会触发[/color][color=#ffd780][b]弋猎印记[/b][/color][color=#e2e8f0]。该伤害视为元素爆发伤害。[/color]
[color=#e2e8f0]图加林会优先攻击处于[/color][color=#ffd780][b]弋猎印记[/b][/color][color=#e2e8f0]效果影响下的敌人。[/color]', 2),
  (7, 10000148, '[color=#FFD780][b]极星辉域[/b][/color]', '[color=#e2e8f0]触发星超导反应时，附近的区域会短暂变化为[/color][color=#ffd780][b]极星辉域[/b][/color][color=#e2e8f0]；处于极星辉域中时，特定角色将会进入[/color][color=#ffd780][b]辉映·星超导[/b][/color][color=#e2e8f0]状态，使其不同技能分别获得对应的强化效果。[/color]', 3),
  (8, 10000133, '[color=#FFD780][b]解算功率[/b][/color]', '[color=#e2e8f0]处于[color=#ffd780][b]解算[/b][/color]模式下时，法洁欧的[color=#ffd780][b]解算功率[/b][/color]会不断上升；解算功率达到上限时，将无法维持或重新进入解算模式。[/color]', 1),
  (9, 10000133, '[color=#FFD780][b]极星辉域[/b][/color]', '触发星超导反应时，附近的区域会短暂变化为[color=#ffd780][b]极星辉域[/b][/color]；处于极星辉域中时，特定角色将会进入[color=#ffd780][b]辉映·星超导[/b][/color]状态，使其不同技能分别获得对应的强化效果。[/color]', 2),
  (10, 10000133, '[color=#FFD780][b]解算[/b][/color]', '进行重击时，法洁欧将会切换至该模式。
处于该模式下时，法洁欧会对前方的敌人进行扫射攻击，并周期性发射冷凝射线，造成[color=#99ffff][b]冰元素范围伤害[/b][/color]。
[color=#ffd780][b]辉映·星超导[/b][/color]：冷凝射线转为造成视为星超导反应伤害的[color=#99ffff][b]冰元素范围伤害[/b][/color]。[/color]', 3),
  (11, 10000133, '[color=#FFD780][b]擢升[/b][/color]', '特殊的伤害提升效果，与其他的伤害提升效果分别独立计算。[/color]', 4),
  (12, 10000132, '[color=#FFD780][b]「狩灾誓锤」[/b][/color]', '值得信任的追猎魔女好伙伴！在一定条件下可以发生元素转化，所有原本由「狩灾誓锤」造成的伤害，都会转为对敌人造成对应元素类型的伤害。
布伦妮可以通过以下方式，召唤出发生元素转化的「狩灾誓锤」：
·布伦妮施放元素战技[color=#ffd780][b]叮铃铃·猎魔之音[/b][/color]对敌人触发扩散反应后的一定时间内，可以施放特殊的元素战技[color=#ffd780][b]咚锵锵·裁魔之惩[/b][/color]；施放该特殊元素战技时，「狩灾誓锤」将会转化为参与先前扩散反应的其他元素类型。
·解锁突破天赋「裁断追惩」后，如果处于「寻猎」模式下的「诱巫饵铃」对敌人触发了扩散反应，则会召唤出一柄依据本次扩散反应进行元素转化的「狩灾誓锤」对敌人进行攻击。[/color]', 1),
  (13, 10000131, '[color=#FFD780][b]虚己之赐[/b][/color]', '[color=#e2e8f0]施放元素战技[/color][color=#ffd780][b]圣言默示·未现之光[/b][/color][color=#e2e8f0]后，尼可会为队伍中附近的所有角色赋予该效果：基于尼可的攻击力，提升攻击力。[/color]
[color=#e2e8f0]满足特定条件后，[/color][color=#ffd780][b]虚己之赐[/b][/color][color=#e2e8f0]效果将会升变为[/color][color=#ffd780][b]圣祝之引[/b][/color][color=#e2e8f0]，进一步提升攻击力。[/color]', 1),
  (14, 10000131, '[color=#FFD780][b]圣祝之引[/b][/color]', '[color=#ffd780][b]虚己之赐[/b][/color][color=#e2e8f0]升变后的效果，能额外提升300点攻击力。[/color]
[color=#e2e8f0]解锁突破天赋「分有」并满足其中的任意「观测」条件后，[/color][color=#ffd780][b]虚己之赐[/b][/color][color=#e2e8f0]将会在剩余持续时间内升变为[/color][color=#ffd780][b]圣祝之引[/b][/color][color=#e2e8f0]：[/color]
[color=#e2e8f0]·受观测的其他角色持续处于场上超过3秒；[/color]
[color=#e2e8f0]·受观测的其他角色为魔导角色。[/color]

[color=#e2e8f0]此外，解锁突破天赋「慕善」后，队伍中附近的当前场上角色的元素伤害命中敌人后，尼可自己拥有的[/color][color=#ffd780][b]虚己之赐[/b][/color][color=#e2e8f0]也会升变为[/color][color=#ffd780][b]圣祝之引[/b][/color][color=#e2e8f0]，持续8秒。[/color]

[color=#e2e8f0]除尼可外，其他角色拥有的[/color][color=#ffd780][b]圣祝之引[/b][/color][color=#e2e8f0]将在退场时还原为[/color][color=#ffd780][b]虚己之赐[/b][/color][color=#e2e8f0]。[/color]', 2),
  (15, 10000130, '[color=#FFD780][b]露米·出击形态[/b][/color]', '[color=#e2e8f0]露米有三种不同的出击形态。[/color]

[color=#ffd780][b]超厉害形态[/b][/color]
[color=#e2e8f0]露米会使用[/color][color=#ffd780][b]捶捶乱打[/b][/color][color=#e2e8f0]不断攻击附近的敌人，每次攻击会造成2次[/color][color=#ffe699][b]岩元素范围伤害[/b][/color][color=#e2e8f0]。[/color]
[color=#e2e8f0]若附近存在月笼，露米则会交替使用[/color][color=#ffd780][b]捶捶乱打[/b][/color][color=#e2e8f0]与[/color][color=#ffd780][b]加力重锤[/b][/color][color=#e2e8f0]，不断攻击附近的敌人；[/color][color=#ffd780][b]加力重锤[/b][/color][color=#e2e8f0]会造成视为月结晶反应伤害的[/color][color=#ffe699][b]岩元素范围伤害[/b][/color][color=#e2e8f0]。[/color]

[color=#ffd780][b]究极厉害形态[/b][/color]
[color=#e2e8f0]露米会使用究极厉害的[/color][color=#ffd780][b]百万吨重锤[/b][/color][color=#e2e8f0]，对附近的敌人造成一次格外强力的、视为月结晶反应伤害的[/color][color=#ffe699][b]岩元素范围伤害[/b][/color][color=#e2e8f0]，并切换至[/color][color=#ffd780][b]普通厉害形态[/b][/color][color=#e2e8f0]。[/color]

[color=#ffd780][b]普通厉害形态[/b][/color]
[color=#e2e8f0]虽然没有其他形态那么厉害，但也很厉害。[/color]
[color=#e2e8f0]露米会以更长的间隔使用[/color][color=#ffd780][b]捶捶乱打[/b][/color][color=#e2e8f0]，不断攻击附近的敌人，每次攻击会造成2次[/color][color=#ffe699][b]岩元素范围伤害[/b][/color][color=#e2e8f0]。[/color]', 1),
  (16, 10000130, '[color=#FFD780][b]擢升[/b][/color]', '特殊的伤害提升效果，与其他的伤害提升效果分别独立计算。', 2),
  (17, 10000129, '[color=#FFD780][b]奇谋[/b][/color]', '[color=#e2e8f0]施放元素战技[/color][color=#ffd780][b]奇兵诡出[/b][/color][color=#e2e8f0]后，洛恩将会切换至该状态。奇谋状态具有如下特性：[/color]
[color=#e2e8f0]·洛恩的普通攻击、重击与下落攻击将转为造成无法被附魔覆盖的[/color][color=#99ffff][b]冰元素伤害[/b][/color][color=#e2e8f0]；[/color]
[color=#e2e8f0]·洛恩的普通攻击或重击命中敌人时，会为洛恩积攒特殊的[/color][color=#ffd780][b]欢悦[/b][/color][color=#e2e8f0]，用于施放特殊元素战技[/color][color=#ffd780][b]镂骨彻心[/b][/color][color=#e2e8f0]；在[/color][color=#ffd780][b]奇谋[/b][/color][color=#e2e8f0]状态下至多施放3次[/color][color=#ffd780][b]镂骨彻心[/b][/color][color=#e2e8f0]，之后无法获得[/color][color=#ffd780][b]欢悦[/b][/color][color=#e2e8f0]。[/color]
[color=#e2e8f0]·队伍中附近的其他角色造成伤害时，会为洛恩积攒特殊的[/color][color=#ffd780][b]争胜[/b][/color][color=#e2e8f0]，用于提升特殊元素战技[/color][color=#ffd780][b]镂骨彻心[/b][/color][color=#e2e8f0]造成的伤害；[/color]
[color=#e2e8f0]·洛恩退场时，奇谋状态将会解除；奇谋状态解除时，[/color][color=#ffd780][b]欢悦[/b][/color][color=#e2e8f0]与[/color][color=#ffd780][b]争胜[/b][/color][color=#e2e8f0]也会清除。[/color]', 1),
  (18, 10000129, '[color=#FFD780][b]欢悦[/b][/color]', '[color=#e2e8f0]在奇谋状态下，洛恩的普通攻击或重击命中敌人时，会获得17点[/color][color=#ffd780][b]欢悦[/b][/color][color=#e2e8f0]，上限为100点。[/color]
[color=#e2e8f0]每0.1秒至多获得一次[/color][color=#ffd780][b]欢悦[/b][/color][color=#e2e8f0]。[/color][color=#ffd780][b]欢悦[/b][/color][color=#e2e8f0]积攒至上限后，洛恩的元素战技[/color][color=#ffd780][b]奇兵诡出[/b][/color][color=#e2e8f0]将会被替换为特殊的元素战技[/color][color=#ffd780][b]镂骨彻心[/b][/color][color=#e2e8f0]。[/color]', 2),
  (19, 10000129, '[color=#FFD780][b]镂骨彻心[/b][/color]', '[color=#e2e8f0]洛恩的[/color][color=#ffd780][b]欢悦[/b][/color][color=#e2e8f0]积攒至上限后，可以施放的特殊元素战技。[/color]
[color=#e2e8f0]命中敌人后消耗所有[/color][color=#ffd780][b]欢悦[/b][/color][color=#e2e8f0]与[/color][color=#ffd780][b]争胜[/b][/color][color=#e2e8f0]，造成[/color][color=#99ffff][b]冰元素伤害[/b][/color][color=#e2e8f0]，并依据消耗的[/color][color=#ffd780][b]争胜[/b][/color][color=#e2e8f0]，提升本次伤害。[/color]', 3),
  (20, 10000129, '[color=#FFD780][b]争胜[/b][/color]', '[color=#e2e8f0]在奇谋状态下，队伍中附近的其他角色造成伤害时，会为洛恩提供的特殊资源，上限为100点。[/color]
[color=#e2e8f0]奇谋状态持续期间，队伍中附近的其他角色造成伤害时，若本次伤害不低于洛恩基础攻击力的1000%，将会为洛恩积攒20点[/color][color=#ffd780][b]争胜[/b][/color][color=#e2e8f0]，否则会为洛恩积攒1点[/color][color=#ffd780][b]争胜[/b][/color][color=#e2e8f0]。[/color]
[color=#e2e8f0]同一个角色每0.1秒至多为洛恩积攒一次[/color][color=#ffd780][b]争胜[/b][/color][color=#e2e8f0]。[/color]', 4),
  (21, 10000128, '[color=#FFD780][b]狂飙突进[/b][/color]', '[color=#e2e8f0]点按施放元素战技[/color][color=#ffd780][b]烈风终坠[/b][/color][color=#e2e8f0]后，法尔伽将切换至该模式。[/color]
[color=#e2e8f0]处于该模式下时，法尔伽的普通攻击与重击造成的伤害提高，无法进行下落攻击；法尔伽进行普通攻击与重击时，将根据队伍中角色的元素类型，使双持的大剑分别造成无法被附魔覆盖的对应元素伤害：[/color]
[color=#e2e8f0]·左手持握的大剑将转为造成无法被附魔覆盖的[/color][color=#80ffd7][b]风元素伤害[/b][/color][color=#e2e8f0]；[/color]
[color=#e2e8f0]·队伍中存在[/color][color=#ff9999][b]火元素[/b][/color][color=#e2e8f0]、[/color][color=#80c0ff][b]水元素[/b][/color][color=#e2e8f0]、[/color][color=#ffacff][b]雷元素[/b][/color][color=#e2e8f0]或[/color][color=#99ffff][b]冰元素[/b][/color][color=#e2e8f0]角色时，右手持握的大剑将按照上述元素类型的优先级，造成无法被附魔覆盖的对应元素伤害。[/color]

[color=#e2e8f0]此外，处于该模式下时，若队伍中存在[/color][color=#ff9999][b]火元素[/b][/color][color=#e2e8f0]、[/color][color=#80c0ff][b]水元素[/b][/color][color=#e2e8f0]、[/color][color=#ffacff][b]雷元素[/b][/color][color=#e2e8f0]或[/color][color=#99ffff][b]冰元素[/b][/color][color=#e2e8f0]角色，法尔伽的元素战技[/color][color=#ffd780][b]烈风终坠[/b][/color][color=#e2e8f0]将会被替换为特殊的元素战技[/color][color=#ffd780][b]四风将起[/b][/color][color=#e2e8f0]。[/color]', 1),
  (22, 10000128, '[color=#FFD780][b]四风将起[/b][/color]', '[color=#e2e8f0]法尔伽的特殊元素战技，对敌人造成无法被附魔覆盖的右手持握大剑的对应元素范围伤害与[/color][color=#80ffd7][b]风元素范围伤害[/b][/color][color=#e2e8f0]。[/color]
[color=#e2e8f0]初始处于冷却，至多拥有2次可使用次数。[/color]
[color=#e2e8f0]法尔伽在[/color][color=#ffd780][b]狂飙突进[/b][/color][color=#e2e8f0]模式下的普通攻击命中敌人时，[/color][color=#ffd780][b]四风将起[/b][/color][color=#e2e8f0]的冷却时间将会缩短0.5秒；每次切换至[/color][color=#ffd780][b]狂飙突进[/b][/color][color=#e2e8f0]模式后，该效果至多触发15次。[/color]
[color=#e2e8f0]此外，法尔伽可以消耗[/color][color=#ffd780][b]四风将起[/b][/color][color=#e2e8f0]的可使用次数，进行不消耗体力的特殊重击[/color][color=#ffd780][b]苍噬[/b][/color][color=#e2e8f0]，造成2次无法被附魔覆盖的右手持握大剑的对应元素伤害与2次[/color][color=#80ffd7][b]风元素伤害[/b][/color][color=#e2e8f0]。[/color]', 2),
  (23, 10000127, '[color=#FFD780][b]「夜莺之歌」[/b][/color]', '[color=#e2e8f0]叶洛亚施放元素爆发[/color][color=#ffd780][b]鉴照无影[/b][/color][color=#e2e8f0]后获得的效果，可以提升当前场上角色造成的[/color][color=#ffe699][b]岩元素伤害[/b][/color][color=#e2e8f0]。[/color]', 1),
  (24, 10000126, '[color=#FFD780][b]月转时隙[/b][/color]', '[color=#e2e8f0]施放元素战技[/color][color=#ffd780][b]天地忽然身[/b][/color][color=#e2e8f0]后，兹白将切换至该模式。该模式至多持续15秒，并具有以下特性：[/color]
[color=#e2e8f0]·进行普通攻击与重击时，将转为造成无法被附魔覆盖的[/color][color=#ffe699][b]岩元素伤害[/b][/color][color=#e2e8f0]；[/color]
[color=#e2e8f0]·元素战技[/color][color=#ffd780][b]天地忽然身[/b][/color][color=#e2e8f0]将会被替换为特殊的元素战技[/color][color=#ffd780][b]灵驹飞踏[/b][/color][color=#e2e8f0]：当兹白拥有至少70点[/color][color=#ffd780][b]「时隙浮光」[/b][/color][color=#e2e8f0]时，兹白可以消耗70点「时隙浮光」，施放灵驹飞踏，造成两次[/color][color=#ffe699][b]岩元素伤害[/b][/color][color=#e2e8f0]，其中的第二段伤害视为月结晶反应伤害。[/color]

[color=#ffd780][b]「时隙浮光」[/b][/color][color=#e2e8f0]上限为100点，兹白可以通过以下方式积攒「时隙浮光」：[/color]
[color=#e2e8f0]·处于[/color][color=#ffd780][b]「月转时隙」[/b][/color][color=#e2e8f0]模式下时，每秒积攒10点「时隙浮光」；[/color]
[color=#e2e8f0]·普通攻击命中敌人时，会积攒5点「时隙浮光」，每0.5秒至多通过这种方式为兹白积攒一次「时隙浮光」。[/color]

[color=#ffd780][b]月兆·满辉[/b][/color][color=#e2e8f0][/color]
[color=#e2e8f0]队伍中附近的角色触发月结晶反应时，也会为兹白积攒35点[/color][color=#ffd780][b]「时隙浮光」[/b][/color][color=#e2e8f0]，每4秒至多通过这种方式为兹白积攒一次「时隙浮光」，施放特殊元素战技[/color][color=#ffd780][b]灵驹飞踏[/b][/color][color=#e2e8f0]将会重置通过这种方式积攒[/color][color=#ffd780][b]「时隙浮光」[/b][/color][color=#e2e8f0]的冷却时间。[/color]

[color=#e2e8f0]施放4次[/color][color=#ffd780][b]灵驹飞踏[/b][/color][color=#e2e8f0]后，或持续时间结束时，兹白将退出该模式。[/color]', 1),
  (25, 10000126, '[color=#FFD780][b]擢升[/b][/color]', '[color=#e2e8f0]特殊的伤害提升效果，与其他的伤害提升效果分别独立计算。[/color]', 2),
  (26, 10000125, '[color=#FFD780][b]草露[/b][/color]', '队伍中的角色触发月绽放反应后，会为队伍提供的资源。
触发月绽放反应后的2.5秒内，每2.5秒便会为队伍提供一枚草露，草露上限为三枚。持续期间，再次触发月绽放反应时，将刷新上述效果的持续时间。', 1),
  (27, 10000125, '[color=#FFD780][b]引力涟漪[/b][/color]', '[color=#e2e8f0]施放元素战技[/color][color=#ffd780][b]万古潮汐[/b][/color][color=#e2e8f0]后，哥伦比娅将唤出[/color][color=#ffd780][b]引力涟漪[/b][/color][color=#e2e8f0]。[/color]
[color=#e2e8f0]引力涟漪将跟随当前场上角色，并持续对周围的敌人造成[/color][color=#80c0ff][b]水元素范围伤害[/b][/color][color=#e2e8f0]。[/color]

[color=#e2e8f0]此外，引力涟漪存在期间，队伍中附近的角色触发月曜反应时，或造成月曜反应伤害时，哥伦比娅将在接下来的2秒内获得新月之示效果，持续积攒[/color][color=#ffd780][b]引力值[/b][/color][color=#e2e8f0]，每2秒可以积攒20点引力值。[/color]
[color=#e2e8f0]引力值上限为60点，且会在引力涟漪持续时间结束时被移除。[/color]
[color=#e2e8f0]当引力值积攒至上限时，将触发特殊的[/color][color=#ffd780][b]引力干涉[/b][/color][color=#e2e8f0]，依据为哥伦比娅积攒最多引力值的月曜反应类型，分别产生不同的效果。若为哥伦比娅积攒最多引力值的月曜反应类型为：[/color]
[color=#e2e8f0]·[/color][color=#ffd780][b]月感电反应[/b][/color][color=#e2e8f0]：引力干涉将造成一次[/color][color=#ffacff][b]雷元素范围伤害[/b][/color][color=#e2e8f0]，该伤害视为月感电反应伤害；[/color]
[color=#e2e8f0]·[/color][color=#ffd780][b]月绽放反应[/b][/color][color=#e2e8f0]：引力干涉将对周围的敌人发射5枚月露之印，造成[/color][color=#99ff88][b]草元素伤害[/b][/color][color=#e2e8f0]，该伤害视为月绽放反应伤害；[/color]
[color=#e2e8f0]·[/color][color=#ffd780][b]月结晶反应[/b][/color][color=#e2e8f0]：引力干涉将造成一次[/color][color=#ffe699][b]岩元素范围伤害[/b][/color][color=#e2e8f0]，该伤害视为月结晶反应伤害。[/color]', 2),
  (28, 10000125, '[color=#FFD780][b]月之领域[/b][/color]', '[color=#e2e8f0]施放元素爆发[/color][color=#ffd780][b]她的乡愁[/b][/color][color=#e2e8f0]后，哥伦比娅唤出的领域。[/color]
[color=#e2e8f0]当前场上角色处于[/color][color=#ffd780][b]月之领域[/b][/color][color=#e2e8f0]中时，队伍中的所有角色造成的月曜反应伤害将会提升。[/color]', 3),
  (29, 10000125, '[color=#FFD780][b]山月草露[/b][/color]', '[color=#e2e8f0]由哥伦比娅的固有天赋[/color][color=#ffd780][b]新月自己的法则[/b][/color][color=#e2e8f0]提供的、特殊的草露资源，与草露分别计算上限与持续时间。[/color]
[color=#e2e8f0]队伍拥有的草露耗尽时，将转而消耗[/color][color=#ffd780][b]山月草露[/b][/color][color=#e2e8f0]。[/color]
[color=#ffd780][b]山月草露[/b][/color][color=#e2e8f0]上限为三枚。[/color]', 4),
  (30, 10000125, '[color=#FFD780][b]擢升[/b][/color]', '特殊的伤害提升效果，与其他的伤害提升效果分别独立计算。', 5),
  (31, 10000124, '[color=#FFD780][b]呼噜噜秘藏瓶[/b][/color]', '[color=#e2e8f0]雅珂达施放元素战技[/color][color=#ffd780][b]奇策·财富分配方案[/b][/color][color=#e2e8f0]后取出的小型元素瓶。[/color]
[color=#e2e8f0]雅珂达处于「掠影追袭」状态下时，若附近的敌人处于[/color][color=#ff9999][b]火元素[/b][/color][color=#e2e8f0]、[/color][color=#80c0ff][b]水元素[/b][/color][color=#e2e8f0]、[/color][color=#ffacff][b]雷元素[/b][/color][color=#e2e8f0]或[/color][color=#99ffff][b]冰元素[/b][/color][color=#e2e8f0]附着下，呼噜噜秘藏瓶会转化为对应的元素类型，并持续进行装填，且会按照[/color][color=#ff9999][b]火元素[/b][/color][color=#e2e8f0]、[/color][color=#80c0ff][b]水元素[/b][/color][color=#e2e8f0]、[/color][color=#ffacff][b]雷元素[/b][/color][color=#e2e8f0]、[/color][color=#99ffff][b]冰元素[/b][/color][color=#e2e8f0]的优先级进行转化。每次施放元素战技后，呼噜噜秘藏瓶至多能进行一次转化。[/color]
[color=#e2e8f0]呼噜噜秘藏瓶装满时，雅珂达将会退出「掠影追袭」状态，对附近的敌人造成一次[/color][color=#80ffd7][b]风元素伤害[/b][/color][color=#e2e8f0]，并清空呼噜噜秘藏瓶。[/color]
[color=#e2e8f0]每次施放元素战技时，雅珂达都会重新取出一个新的呼噜噜秘藏瓶。[/color]

[color=#ffd780][b]月兆·满辉[/b][/color][color=#e2e8f0]：[/color][color=#ffd780][b]呼噜噜秘藏瓶[/b][/color][color=#e2e8f0]装满时，雅珂达不会立刻清空[/color][color=#ffd780][b]呼噜噜秘藏瓶[/b][/color][color=#e2e8f0]，而是会在接下来的一段时间内，持续消耗瓶中装填的元素，并间歇性向附近的敌人发射[/color][color=#ffd780][b]软绒绒猫猫球[/b][/color][color=#e2e8f0]，造成[/color][color=#ffd780][b]呼噜噜秘藏瓶[/b][/color][color=#e2e8f0]对应元素类型的伤害。[/color]', 1),
  (32, 10000124, '[color=#FFD780][b]猫型家用互助协调器[/b][/color]', '[color=#e2e8f0]曾是宝藏猎人的雅珂达随身携带的小道具之一，施放元素爆发[/color][color=#ffd780][b]秘器·猎人的七道具[/b][/color][color=#e2e8f0]后取出。[/color]
[color=#e2e8f0]猫型家用互助协调器将会持续为队伍中自己的当前场上角色恢复生命值；如果受到治疗的角色生命值高于70%，还会同时为队伍中附近生命值最低的角色恢复生命值。[/color]

[color=#ffd780][b]月兆·满辉[/b][/color][color=#e2e8f0]：若附近的敌人处于[/color][color=#ff9999][b]火元素[/b][/color][color=#e2e8f0]、[/color][color=#80c0ff][b]水元素[/b][/color][color=#e2e8f0]、[/color][color=#ffacff][b]雷元素[/b][/color][color=#e2e8f0]或[/color][color=#99ffff][b]冰元素[/b][/color][color=#e2e8f0]附着下，猫型家用互助协调器将会转化为对应的元素类型，并会按照[/color][color=#ff9999][b]火元素[/b][/color][color=#e2e8f0]、[/color][color=#80c0ff][b]水元素[/b][/color][color=#e2e8f0]、[/color][color=#ffacff][b]雷元素[/b][/color][color=#e2e8f0]、[/color][color=#99ffff][b]冰元素[/b][/color][color=#e2e8f0]的优先级进行转化。每次取出猫型家用互助协调器后，至多通过这种方式进行一次元素转化。触发元素转化后，猫型家用互助协调器将会间歇性攻击附近至多3名敌人，造成对应元素伤害。[/color]', 2),
  (33, 10000123, '[color=#FFD780][b]精质转变[/b][/color]', '[color=#e2e8f0]杜林施放元素战技[/color][color=#ffd780][b]二元式·聚分熔炼[/b][/color][color=#e2e8f0]后获得的效果，持续6秒。[/color]
[color=#e2e8f0]持续期间，杜林可以通过点按元素战技进入[/color][color=#ffd780][b]白化之是[/b][/color][color=#e2e8f0]状态，或是通过点按普通攻击进入[/color][color=#ffd780][b]黑度之否[/b][/color][color=#e2e8f0]状态。[/color]
[color=#e2e8f0]在两种状态下，杜林会获得不同的强化效果，并可以分别施放不同的元素爆发。[/color]', 1),
  (34, 10000122, '[color=#FFD780][b]影舞[/b][/color]', '[color=#e2e8f0]施放元素战技[/color][color=#ffd780][b]弈术·千夜一舞[/b][/color][color=#e2e8f0]后，奈芙尔将会进入该状态。[/color]
[color=#e2e8f0]处于「影舞」状态下时，若拥有至少1枚草露，奈芙尔施放的重击将会被替换为特殊的重击「幻戏」。[/color]
[color=#e2e8f0]「影舞」状态将在奈芙尔施放3次幻戏或持续时间结束时解除。[/color]', 1),
  (35, 10000122, '[color=#FFD780][b]草露[/b][/color]', '队伍中的角色触发月绽放反应后，会为队伍提供的资源。
触发月绽放反应后的2.5秒内，每2.5秒便会为队伍提供一枚草露，草露上限为三枚。持续期间，再次触发月绽放反应时，将刷新上述效果的持续时间。', 2),
  (36, 10000122, '[color=#FFD780][b]幻戏[/b][/color]', '[color=#e2e8f0]处于元素战技[/color][color=#ffd780][b]弈术·千夜一舞[/b][/color][color=#e2e8f0]造成的「影舞」状态下时，若拥有至少1枚草露，奈芙尔施放的重击将会被替换为特殊的、不消耗体力的重击「幻戏」。[/color]
[color=#e2e8f0]奈芙尔召唤出自身的虚影，对敌人发起协同攻击，自身与虚影分别依次造成2/3段[/color][color=#99ff88][b]草元素范围伤害[/b][/color][color=#e2e8f0]。虚影造成的伤害视为月绽放反应伤害，每次施放幻戏后首次召唤虚影时，将消耗一枚草露。[/color]', 3),
  (37, 10000122, '[color=#FFD780][b]伪秘之帷[/b][/color]', '[color=#e2e8f0]奈芙尔通过突破天赋「月下的豪赌」吸收诳言之核后获得的效果，可以提升幻戏造成的伤害。[/color]
[color=#e2e8f0]每层「伪秘之帷」都会使奈芙尔施放的幻戏造成比原本高8%的伤害，初始至多叠加3层，持续9秒，每层独立计算持续时间。[/color]', 4),
  (38, 10000122, '[color=#FFD780][b]擢升[/b][/color]', '[color=#e2e8f0]特殊的伤害提升效果，与其他的伤害提升效果分别独立计算。[/color]', 5),
  (39, 10000120, '[color=#FFD780][b]雷霆交响[/b][/color]', '[color=#e2e8f0]消耗更少的元素能量便可以施放的特殊元素爆发。菲林斯造成一次视为月感电反应伤害的[/color][color=#ffacff][b]雷元素范围伤害[/b][/color][color=#e2e8f0]。[/color]
[color=#ffd780][b]月兆·满辉[/b][/color][color=#e2e8f0]：若附近存在雷暴云，还会额外造成一次视为月感电反应伤害的[/color][color=#ffacff][b]雷元素范围伤害[/b][/color][color=#e2e8f0]。[/color]', 1),
  (40, 10000120, '[color=#FFD780][b]擢升[/b][/color]', '特殊的伤害提升效果，与其他的伤害提升效果分别独立计算。', 2),
  (41, 10000119, '[color=#FFD780][b]霜林圣域[/b][/color]', '[color=#e2e8f0]用以护守咏月使的术阵，通过施放元素战技[/color][color=#ffd780][b]圣言述咏·终宵永眠[/b][/color][color=#e2e8f0]唤出。[/color]
[color=#e2e8f0]霜林圣域将跟随当前场上角色，每2秒对术阵中的敌人造成一次[/color][color=#99ff88][b]草元素范围伤害[/b][/color][color=#e2e8f0]，该伤害视为元素战技伤害。[/color]', 1),
  (42, 10000119, '[color=#FFD780][b]草露[/b][/color]', '[color=#e2e8f0]队伍中的角色触发月绽放反应后，会为队伍提供的资源。[/color]
[color=#e2e8f0]触发月绽放反应后的2.5秒内，每2.5秒便会为队伍提供一枚草露，草露上限为三枚。持续期间，再次触发月绽放反应时，将刷新上述效果的持续时间。[/color]', 2),
  (43, 10000119, '[color=#FFD780][b]月咏[/b][/color]', '[color=#e2e8f0]用以纺出祷歌的乐节，可以在施放元素爆发时或施放元素爆发后的一段时间内转化为提升绽放、超绽放、烈绽放、月绽放反应伤害的苍色祷歌。[/color]
[color=#e2e8f0]菈乌玛消耗草露以长按施放元素战技[/color][color=#ffd780][b]圣言述咏·终宵永眠[/b][/color][color=#e2e8f0]时，依据消耗的草露数，每一枚草露都会使菈乌玛获得一层「月咏」。[/color]', 3),
  (44, 10000119, '[color=#FFD780][b]苍色祷歌[/b][/color]', '[color=#e2e8f0]咏月使世代传承的祷歌，能够提升绽放、超绽放、烈绽放、月绽放反应造成的伤害。[/color]

[color=#e2e8f0]菈乌玛可以通过以下方式获得苍色祷歌：[/color]
[color=#e2e8f0]·施放元素爆发[/color][color=#ffd780][b]圣言述咏·众心为月[/b][/color][color=#e2e8f0]时；[/color]
[color=#e2e8f0]·触发元素爆发[/color][color=#ffd780][b]圣言述咏·众心为月[/b][/color][color=#e2e8f0]中消耗「月咏」的效果时；[/color]
[color=#e2e8f0]·触发命之座[/color][color=#ffd780][b]「我愿将这血与泪奉予月明」[/b][/color][color=#e2e8f0]中霜林圣域的效果时。[/color]

[color=#e2e8f0]队伍中的角色造成绽放、超绽放、烈绽放、月绽放反应伤害时，将消耗一层「苍色祷歌」，提升造成的伤害，提升值基于菈乌玛的元素精通。上述伤害同时命中多名敌人时，会依据命中敌人的数量消耗「苍色祷歌」层数。[/color]
[color=#e2e8f0]每层「苍色祷歌」独立计算持续时间。[/color]', 4),
  (45, 10000119, '[color=#FFD780][b]擢升[/b][/color]', '[color=#e2e8f0]特殊的伤害提升效果，与其他的伤害提升效果分别独立计算。[/color]', 5),
  (46, 10000116, '[color=#FFD780][b]薇尔琪塔[/b][/color]', '[color=#e2e8f0]与伊涅芙一同战斗的好帮手，可以通过施放元素战技或元素爆发召唤至场上。[/color]
[color=#e2e8f0]若周围存在敌人，每隔2秒，薇尔琪塔将快速移动至一名敌人附近，对其进行放电攻击，造成[/color][color=#ffacff][b]雷元素范围伤害[/b][/color][color=#e2e8f0]。[/color]
[color=#e2e8f0]同时至多存在一个伊涅芙自己创造的薇尔琪塔。[/color]

[color=#e2e8f0]此外，在挪德卡莱，似乎可以通过某种途径来改变薇尔琪塔的外观…[/color]', 1),
  (47, 10000005, '[color=#FFD780][b]寒辉[/b][/color]', '[color=#e2e8f0]旅行者凝结的[/color][color=#ffd780][b]栗烈寒星[/b][/color][color=#e2e8f0]发射冰晶命中敌人时，或解锁天赋[/color][color=#ffd780][b]异邦的层冰[/b][/color][color=#e2e8f0]后进行[/color][color=#ffd780][b]重击·冰凝[/b][/color][color=#e2e8f0]后，将会获得的特殊效果。该效果至多叠加8层。[/color]
[color=#e2e8f0]施放元素爆发[/color][color=#ffd780][b]聚冰成锋[/b][/color][color=#e2e8f0]时，旅行者会消耗所有的[/color][color=#ffd780][b]寒辉[/b][/color][color=#e2e8f0]层数，提升本次元素爆发造成的伤害。若消耗层数为8层，则还会提升本次元素爆发造成伤害的段数。[/color]', 1),
  (48, 10000007, '[color=#FFD780][b]寒辉[/b][/color]', '[color=#e2e8f0]旅行者凝结的[/color][color=#ffd780][b]栗烈寒星[/b][/color][color=#e2e8f0]发射冰晶命中敌人时，或解锁天赋[/color][color=#ffd780][b]异邦的层冰[/b][/color][color=#e2e8f0]后进行[/color][color=#ffd780][b]重击·冰凝[/b][/color][color=#e2e8f0]后，将会获得的特殊效果。该效果至多叠加8层。[/color]
[color=#e2e8f0]施放元素爆发[/color][color=#ffd780][b]聚冰成锋[/b][/color][color=#e2e8f0]时，旅行者会消耗所有的[/color][color=#ffd780][b]寒辉[/b][/color][color=#e2e8f0]层数，提升本次元素爆发造成的伤害。若消耗层数为8层，则还会提升本次元素爆发造成伤害的段数。[/color]', 1),
  (49, 10000007, '[color=#FFD780][b]额外强化效果[/b][/color]', '每与一种元素进行过共鸣，旅行者便会获得对应的属性提升：
[color=#b7f3ce]风元素[/color]：暴击率提升10%；
[color=#ecd87b]岩元素[/color]：防御力提升20%；
[color=#f3b0fa]雷元素[/color]：元素充能效率提升20%；
[color=#bee855]草元素[/color]：元素精通提升60点；
[color=#8ebefa]水元素[/color]：生命值提升20%；
[color=#f19e9c]火元素[/color]：攻击力提升20%；
[color=#b1fcfe]冰元素[/color]：暴击伤害提升20%。', 2),
  (50, 10000005, '[color=#FFD780][b]额外强化效果[/b][/color]', '每与一种元素进行过共鸣，旅行者便会获得对应的属性提升：
[color=#b7f3ce]风元素[/color]：暴击率提升10%；
[color=#ecd87b]岩元素[/color]：防御力提升20%；
[color=#f3b0fa]雷元素[/color]：元素充能效率提升20%；
[color=#bee855]草元素[/color]：元素精通提升60点；
[color=#8ebefa]水元素[/color]：生命值提升20%；
[color=#f19e9c]火元素[/color]：攻击力提升20%；
[color=#b1fcfe]冰元素[/color]：暴击伤害提升20%。', 2);

