INSERT INTO "perilous_trail_bosses" ("id", "challenge_id", "difficulty", "boss_index", "boss_name", "boss_image", "boss_level", "boss_hp", "advantages", "disadvantages", "details", "sort_order", "hidden_info") VALUES
  (1257, 73, 'treacherous', 1, '[note="抗性 10%"]深罪浸礼者·锐言[/note]', 'UI_MonsterIcon_Invoker_Archdeacon.webp', 100, '2.691.919', '{6}{2}{5}元素角色', NULL, '[color=#cbd5e1][color=#f1f5f9]元素之环·多相[/color]
[color=#cbd5e1]战斗中，会在场上创造[color=#ffd780][b]雷元素、火元素和水元素[/b][/color]的元素之环，并进行吟唱以准备发动威力强大的攻击，一段时间后引爆所有的元素之环。如果能够[color=#ffd780][b]通过元素反应破坏所有的元素之环[/b][/color]，就能打断敌人的吟唱并使其瘫痪一段时间。[/color]
[color=#f1f5f9]元素护罩·多相[/color]
[color=#cbd5e1]战斗中，会依次展开[color=#ffd780][b]雷元素护罩、火元素护罩和水元素护罩[/b][/color]来保护自身，同时根据元素护罩的类型改变自身的攻击方式。[color=#ffd780][b]通过元素反应破除一种元素护罩[/b][/color]后，该敌人就会切换元素形态并展开对应元素护罩；全部的三种护罩都被破除后，该敌人会瘫痪一段时间。[/color]
[/color]
[color=#cbd5e1][/color][i][color=#cbd5e1]因为深渊的力量取得「进化」而获得了多余的肢体的深渊魔物。能够驱役多种元素的力量。[/color]
[color=#cbd5e1]在深渊魔物中的独特地位赋予了它们非同寻常的压迫感，不幸死于其手的生灵则将恐惧融入地脉的记忆，使得它们的低语化为刀刃般的禁咒…[/color][/i][color=#cbd5e1][/color]', 0, NULL),
  (1258, 73, 'treacherous', 2, '[note="抗性 10%"]历经百战的暝视龙·苦寒[/note]', 'UI_MonsterIcon_Natsaurus_Shamansaurus_Normal.webp', 100, '4.420.030', '{1}元素角色
远程攻击角色
聚集能力角色', '近战攻击角色', '[color=#cbd5e1][color=#f1f5f9]强音震波[/color]
[color=#cbd5e1]战斗中，每隔一段时间就会腾跃升空，随后在空中停留一段时间，不断释放强音震波进行攻击。[/color]
[color=#f1f5f9]冰霰骤袭[/color]
[color=#cbd5e1]战斗中，会展开[color=#ffd780][b]冰元素护罩[/b][/color]保护自身，并腾跃至空中，持续在大范围内造成伤害。一段时间后，将释放「冰霰骤袭」，对大范围内的我方角色造成极高伤害。[color=#ffd780][b]通过元素反应破除护罩[/b][/color]，即可将敌人击落至地面，使其受到一次高额伤害，并打断其攻击准备。[/color]
[color=#f1f5f9]协醒之炬[/color]
[color=#cbd5e1]场上的边缘位置将出现3个特殊火炬，在火炬附近通过重击或瞄准射击命中敌人时，将额外造成一次火元素伤害。[/color]
[/color]
[color=#cbd5e1][/color][i][color=#cbd5e1]能够利用生长出的覆羽进行腾跃，亦是唯一一种掌握了进入「灵觉」状态技巧的龙。[/color]
[color=#cbd5e1]然而强大的感知力有时并非祝福。在地脉乱流的裹挟下，它的羽翼不复温暖，无数苦楚与憎恶正悄然凝结为寒冰…[/color][/i][color=#cbd5e1][/color]', 0, NULL),
  (1259, 73, 'treacherous', 3, '[note="抗性
{7} 70%
其他 10%"]实验性场力发生装置·增幅[/note]', 'UI_MonsterIcon_MachinaIustitia_Gravitas.webp', 100, '4.818.053', '下落攻击角色', NULL, '[color=#cbd5e1][color=#f1f5f9]重力核心[/color]
[color=#cbd5e1]战斗中，会显露出荒性的能源特征以展开重力削减力场战斗，并[color=#ffd780][b]在地面上产生无法被闪避的引力冲击波[/b][/color]。在力场中，角色的跳跃高度会获得显著提升。力场展开期间，暴露的荒性核心受到3次芒性攻击就会湮灭，从而导致重力削减力场关闭。[/color]
[/color]
[color=#cbd5e1][/color][i][color=#cbd5e1]枫丹动能工程科学研究院的作品，拥有「抵消」重力的效果，因为事故而失控。[/color]
[color=#cbd5e1]尽管它金属外壳上仍旧光辉熠熠，但在地脉扭曲的记忆中，这一大型装置早已背离了过往的设计目的，徒留散播毁灭的机能…[/color][/i][color=#cbd5e1][/color]', 0, NULL),
  (1260, 73, 'fearless', 1, '[note="抗性 10%"]深罪浸礼者·肃烈狂音[/note]', 'UI_MonsterIcon_Invoker_Archdeacon.webp', 107, '5.213.725', '{6}{2}{5}元素角色', NULL, '[color=#cbd5e1][color=#f1f5f9]元素护罩·纷变狂乱[/color]
[color=#cbd5e1]受到地脉紊乱的影响，战斗开始后，该敌人会依次展开[color=#ffd780][b]雷元素护罩、火元素护罩和水元素护罩[/b][/color]来保护自身，同时根据元素护罩的类型改变自身的攻击方式。[color=#ffd780][b]通过元素反应破除一种元素护罩[/b][/color]后，该敌人将根据[color=#ffd780][b]护罩抵挡的伤害值[/b][/color]受到一次高额伤害，然后切换元素形态并展开对应元素护罩；全部的三种护罩都被破除后，敌人会瘫痪一段时间。[/color]
[/color]
[color=#cbd5e1][/color][i][color=#cbd5e1]因为深渊的力量取得「进化」而获得了多余的肢体的深渊魔物。能够驱役多种元素的力量。[/color]
[color=#cbd5e1]在地脉扭曲的追忆中，它们跃升为狂乱的破坏者，以其亵渎的力量掀起接踵而至的灾厄浪潮…[/color][/i][color=#cbd5e1][/color]', 0, NULL),
  (1261, 73, 'fearless', 2, '[note="抗性 10%"]历经百战的暝视龙·霜雪苛念[/note]', 'UI_MonsterIcon_Natsaurus_Shamansaurus_Normal.webp', 105, '4.344.257', '{1}元素角色
远程攻击角色
聚集能力角色', '近战攻击角色', '[color=#cbd5e1][color=#f1f5f9]强音震波·连奏[/color]
[color=#cbd5e1]受到地脉紊乱的影响，会具有更高的所有抗性；在战斗中，会更为频繁地腾跃升空，在空中停留一段时间，并不断释放强音震波进行攻击。[/color]
[color=#f1f5f9]冰霰骤袭·袤攻[/color]
[color=#cbd5e1]战斗中，会展开[color=#ffd780][b]冰元素护罩[/b][/color]保护自身，并腾跃至空中为「冰霰骤袭」进行准备，一段时间后释放「冰霰骤袭」，[color=#ffd780][b]使我方场上的角色直接倒下[/b][/color]。[color=#ffd780][b]通过元素反应破除护罩[/b][/color]，即可将敌人击落至地面，根据[color=#ffd780][b]护罩抵挡的伤害值[/b][/color]使其受到一次高额伤害，并打断其攻击准备。该敌人准备上述攻击时，我方队伍中所有角色将[color=#ffd780][b]恢复元素能量、战意或蛇之狡谋[/b][/color]。一段时间后如果护罩仍未破除，地面上将出现「冰霰之阵」：[color=#ffd780][b]通过元素反应逐一破坏「冰霰之阵」[/b][/color]，也可以逐渐破除该敌人的冰元素护罩。[/color]
[color=#f1f5f9]扰乱风涡[/color]
[color=#cbd5e1]受到地脉紊乱的影响，该敌人在进行「冰霰骤袭」的准备时，场上将出现「扰乱风涡」，造成[color=#ffd780][b]不分敌我[/b][/color]的冰元素范围伤害。「扰乱风涡」命中该敌人时，将使其[color=#ffd780][b]风元素抗性[/b][/color]降低，并削减其护罩。
此外，「扰乱风涡」可被牵引效果影响，改变移动路径。[/color]
[/color]
[color=#cbd5e1][/color][i][color=#cbd5e1]能够利用生长出的覆羽进行腾跃，亦是唯一一种掌握了进入「灵觉」状态技巧的龙。[/color]
[color=#cbd5e1]它观测到一切苦楚和悲痛，尽被地脉的扭曲追忆吞噬，化作极寒的霜雪风暴，带来无尽的混乱…[/color][/i][color=#cbd5e1][/color]', 0, NULL),
  (1262, 73, 'fearless', 3, '[note="抗性
{7} 70%
其他 10%"]实验性场力发生装置·极端势能[/note]', 'UI_MonsterIcon_MachinaIustitia_Gravitas.webp', 105, '13.231.421', '下落攻击角色', NULL, '[color=#cbd5e1][color=#f1f5f9]重力核心·深度过载[/color]
[color=#cbd5e1]受到地脉紊乱的影响，会在战斗中展开重力削减力场，使角色的跳跃高度获得显著提升，并且每次跳跃至一定高度，角色的攻击力都会在1.5秒内大幅提升。力场持续期间，每隔一段时间就会[color=#ffd780][b]在地面上产生无法被闪避的引力冲击波[/b][/color]。每经过5秒，引力冲击波的威力和频率就会获得1层强化；每受到一次[color=#ffd780][b]下落攻击[/b][/color]，就会移除1层引力冲击波强化。[/color]
[color=#f1f5f9]强韧核心[/color]
[color=#cbd5e1]受到地脉紊乱的影响，荒性核心变得更加坚固，即使在受到[color=#ffd780][b]3次芒性攻击[/b][/color]后，也不再会导致重力削减力场关闭。[/color]
[/color]
[color=#cbd5e1][/color][i][color=#cbd5e1]枫丹动能工程科学研究院的作品，拥有「抵消」重力的效果，因为事故而失控。[/color]
[color=#cbd5e1]在紊乱地脉的作用下，其核心狂暴异常，释放的重力场能量如海啸般奔涌，仿佛要将大地倾覆…[/color][/i][color=#cbd5e1][/color]', 0, NULL),
  (1263, 73, 'desperate', 1, '[color=#ef4444][note="抗性 10%"]深罪浸礼者·肃烈狂音[/note][/color]', 'UI_Img_LeyLineChallenge_Archdeacon.png', 110, '10.902.915', '{6}{2}{5}元素角色', NULL, '[color=#cbd5e1][color=#f1f5f9]元素护罩·纷变狂乱[/color]
[color=#cbd5e1]受到地脉紊乱的影响，战斗开始后，该敌人会依次展开[color=#ffd780][b]雷元素护罩、火元素护罩和水元素护罩[/b][/color]来保护自身，同时根据元素护罩的类型改变自身的攻击方式。[color=#ffd780][b]通过元素反应破除一种元素护罩[/b][/color]后，该敌人将根据[color=#ffd780][b]护罩抵挡的伤害值[/b][/color]受到一次高额伤害，然后切换元素形态并展开对应元素护罩；全部的三种护罩都被破除后，敌人会瘫痪一段时间。[/color]
[/color]
[color=#cbd5e1][/color][i][color=#cbd5e1]因为深渊的力量取得「进化」而获得了多余的肢体的深渊魔物。能够驱役多种元素的力量。[/color]
[color=#cbd5e1]在地脉扭曲的追忆中，它们跃升为狂乱的破坏者，以其亵渎的力量掀起接踵而至的灾厄浪潮…[/color][/i][color=#cbd5e1][/color]', 0, '1. 会依次展开雷元素、火元素、水元素护盾，每次破除时将损失生命值，全部破除后敌人将瘫痪一段时间
2. 护盾量：12U / 18U / 18U（大世界的 150%）。
3. 损失生命值：50% 护盾受到的伤害，不超过 12.5% 生命值，不计入护盾自身元素'),
